import json, importlib.util, sys
from pathlib import Path
from collections import Counter
spec=importlib.util.spec_from_file_location("memory_lib","harnesses/precedent_audit/solver/tools/memory_lib.py")
ml=importlib.util.module_from_spec(spec); sys.modules['memory_lib']=ml; spec.loader.exec_module(ml)
rows=[json.loads(l) for l in open('history/results/samples.jsonl')]
rows=[r for r in rows if r['candidate']=='considered_unit_audit']
def parse_law(t):
    import re
    t=(t or '').strip()
    m=re.search(r"\[罪名\](.*?)(?:<eoa>|$)",t)
    if m: t=m.group(1).strip()
    t=re.sub(r"<eoa>.*","",t).strip()
    for sep in [";","；",",","，","、"]:
        if sep in t: return {p.strip() for p in t.split(sep) if p.strip()}
    return {t} if t else set()
stats=Counter(); detail=[]
for task in ['LawBench','Symptom2Disease','USPTO']:
    mem=json.loads(Path(f'history/candidates/considered_unit_audit/{task}/memory.json').read_text())
    view=ml.MemoryView(mem)
    for r in [x for x in rows if x['task']==task]:
        d=json.load(open(f"history/candidates/considered_unit_audit/{task}/conversations/{r['example_index']:04d}/sample-{r['sample_index']}.json"))
        u=d['messages'][1]['content']; txt=u[0]['text'] if isinstance(u,list) else str(u)
        q=txt.split('REFERENCE PROFILE')[0].strip()
        fired=False
        for m in d['messages']:
            for tc in (m.get('tool_calls') or []):
                fn=tc.get('function') or {}
                if fn.get('name')!='check_answer': continue
                args=json.loads(fn.get('arguments') or '{}')
                out=view.check(args.get('draft_answer') or '', q, args.get('considered') or '')
                if 'The facts decide between them' in out: fired=True
        if not fired: continue
        # was the answer correct, and did the specific relative match the gold?
        if task=='LawBench':
            gold=parse_law(r['target']); pred=parse_law(r['prediction'])
            spec_units=set()
            for m in d['messages']:
                for tc in (m.get('tool_calls') or []):
                    fn=tc.get('function') or {}
                    if fn.get('name')!='check_answer': continue
                    args=json.loads(fn.get('arguments') or '{}')
                    out=view.check(args.get('draft_answer') or '', q, args.get('considered') or '')
                    for line in out.split('\n'):
                        if 'The facts decide between them' in line:
                            import re
                            spec_units |= set(re.findall(r"'([^']+)' = ", line))
                        if 'use only as part of' in line:
                            import re
                            spec_units |= set(re.findall(r"unit\(s\) ([^.]*)\.", line)[0].split(',')) if re.findall(r"unit\(s\) ([^.]*)\.", line) else set()
            spec_units={s.split(' (')[0].strip() for s in spec_units if s.strip()}
        else:
            gold={(r['target'] or '').strip()}; pred={(r['prediction'] or '').strip()}
            spec_units=set()
        key = 'correct_sample' if r['was_correct'] else 'wrong_sample'
        stats[key]+=1
        if spec_units & gold: stats[key+'_+_flagged_unit_in_gold']+=1
        if spec_units and not (spec_units & gold): stats[key+'_+_flagged_unit_not_in_gold']+=1
        detail.append((task, r['example_index'], r['was_correct'], sorted(spec_units)[:3], sorted(gold)[:3]))
print(dict(stats))
for x in detail[:20]: print(x)
